/// <summary>
/// PricingAttribute of table <c>WHSInventTable</c> field ItemId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeWHSInventTableItemId extends GUPPricingAttributeWHSInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventTable, ItemId);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::String);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by ItemId
    {
        if (! ret.in(wHSInventTable.ItemId))
        {
            ret.add(wHSInventTable.ItemId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, ItemId));
    qbr.value(queryValue(_value));
}
